mapper.update:
UPDATE alphafrog_agent_run_service_lease SET
    renewed_at = CURRENT_TIMESTAMP,
    expires_at = CURRENT_TIMESTAMP + #{ttlMillis} * INTERVAL '1 millisecond'
WHERE run_id = #{runId}
  AND owner_instance_id = #{owner}
  AND fencing_token = #{fencingToken}

UPDATE alphafrog_agent_run_service_lease SET
    expires_at = CURRENT_TIMESTAMP
WHERE run_id = #{runId}
  AND owner_instance_id = #{owner}
  AND fencing_token = #{fencingToken}

mapper.select:
SELECT run_id, owner_instance_id, fencing_token, acquired_at, renewed_at, expires_at
FROM alphafrog_agent_run_service_lease
WHERE run_id = #{runId}
